INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "资治通鉴·卷259", "source_type": "primary", "author": "司马光等", "edition": "仓库电子文本；未核纸本。疑似转录讹字保留并单独注明。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/tongjian/259.txt", "note": "卷259乾宁元年条；书、卷、年、段落及行号见批次账本。", "id": "ee2a8086-0e0a-5257-8fa6-23127b09f219"}, {"title": "旧五代史·卷1·梁太祖纪·鱼山战起", "source_type": "primary", "author": "薛居正等", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/18%E6%97%A7%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L24", "note": "原PDF第24页，只补当前主线段落。", "id": "b88f38b7-708b-52a7-a583-49b9bd2a4c19"}, {"title": "旧五代史·卷1·梁太祖纪·鱼山火攻", "source_type": "primary", "author": "薛居正等", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/18%E6%97%A7%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L25", "note": "原PDF第25页，只补当前主线段落。", "id": "bbedb69a-d697-5447-8b5a-c4051bef75d0"}, {"title": "旧五代史·卷53·李存孝传·出城前", "source_type": "primary", "author": "薛居正等", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/18%E6%97%A7%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L1274", "note": "原PDF第1274页，只补当前主线段落。", "id": "0bb71145-d0df-5e52-b224-a576a99afadf"}, {"title": "旧五代史·卷53·李存孝传·出城与车裂", "source_type": "primary", "author": "薛居正等", "edition": "仓库PDF派生电子文本；逐字及换行保留，未核纸本。", "url": "https://github.com/greed-216/histree/blob/17a0b9a305d40d6371bbdd66d1827c8f2f7321fa/resources/derived/twenty-four-histories/18%E6%97%A7%E4%BA%94%E4%BB%A3%E5%8F%B2.jsonl#L1275", "note": "原PDF第1275页，只补当前主线段落。", "id": "4a519788-5a4f-5e91-9760-449eaf003566"}]'::jsonb)
