INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "李杰", "aliases": ["李敏", "唐昭宗"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：李杰。", "biography": null, "status": "draft", "id": "48935190-c754-5bda-bdcd-382c77cb2de0"}, {"name": "李茂贞", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“岐王在唐亡后开府置百官”中为开府者。", "biography": null, "status": "draft", "id": "af9a00d1-c748-5b5f-9175-1af19530d83d"}, {"name": "李匡筹", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：李匡筹。", "biography": null, "status": "draft", "id": "279717fd-44f2-5b26-a549-6d7701dc5746"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "朱瑄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑄。", "biography": null, "status": "draft", "id": "dcaf5869-c45e-5845-b02f-6418dd1f22eb"}, {"name": "朱瑾", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：朱瑾。", "biography": null, "status": "draft", "id": "e4226d41-278e-53c7-9e01-7e3572231e8e"}, {"name": "郑綮", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：郑綮。", "biography": null, "status": "draft", "id": "b5e0fd59-8980-562e-a747-8b0be8310ddc"}, {"name": "邓处讷", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259景福二年条所见人物：邓处讷。", "biography": null, "status": "draft", "id": "53fdc66b-d182-5faf-896e-04db37e18b62"}, {"name": "张钧", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：张钧。", "biography": null, "status": "draft", "id": "3ba7b870-0eb2-53b7-9a07-c3b6455f7b01"}, {"name": "张鐇", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：张鐇。", "biography": null, "status": "draft", "id": "38bbd1fe-ab5d-5cd6-95e7-8189597f688f"}, {"name": "吴讨", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：吴讨。", "biography": null, "status": "draft", "id": "41428183-0ec8-54a2-8fc7-eaa2e028ada8"}, {"name": "杨行密", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：杨行密。", "biography": null, "status": "draft", "id": "ad75628e-5958-5672-9403-eb349ca77e6e"}, {"name": "李存孝", "aliases": ["安敬思"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存孝，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "d25efb4e-74a3-5bab-b1e4-a79cee0716c3"}, {"name": "李克用", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 908, "description": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "biography": "河东晋王，李存勖之父。908年去世，临终命李存勖继承军府。此处的晋不等于后来的后晋。", "status": "draft", "id": "04af206e-fa86-581c-86b9-87a78a8d59a5"}, {"name": "刘氏（李克用妻）", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的刘氏（李克用妻），在此段中为劝阻者。", "biography": null, "status": "draft", "id": "38841ebd-e50c-5bba-ba86-02941b1a7ed3"}, {"name": "李存信", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的李存信，在此段中为李克用养子。", "biography": null, "status": "draft", "id": "31ad8087-ed47-5400-bf8a-47f2edb81920"}, {"name": "王镕", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加授王镕、罗绍威、王处直官衔”中为受授者。", "biography": null, "status": "draft", "id": "a3d42aab-7a1f-51f4-84bc-35192b430637"}, {"name": "薛阿檀", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257文德元年条所见人物：薛阿檀。", "biography": null, "status": "draft", "id": "094f14b4-b42c-5b4a-ae23-b05f486a4370"}, {"name": "马师素", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷259乾宁元年条所见人物：马师素。", "biography": null, "status": "draft", "id": "2bab8dea-66aa-519e-b559-4c575ce41e9d"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "昭宗赦天下，改元乾宁", "start_year": 894, "end_year": 894, "time_original": "894年春正月乙丑朔", "dynasty": "唐", "description": "朝廷在正月初一赦天下，改元乾宁。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b2ecd0ad-d4eb-5d37-b30a-d666fdb62796"}, {"title": "李茂贞入朝，陈兵自卫后归镇", "start_year": 894, "end_year": 894, "time_original": "894年正月条；数日归镇", "dynasty": "唐", "description": "李茂贞入朝，广陈兵力自卫，数日后返回所镇。", "phases": [], "location_name": "朝廷、凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "1bed964d-835c-5afe-b2b1-bacc133575ba"}, {"title": "李匡筹正式受任卢龙节度使", "start_year": 894, "end_year": 894, "time_original": "894年正月条；具体日未载", "dynasty": "唐", "description": "朝廷任李匡筹为卢龙节度使。", "phases": [], "location_name": "卢龙", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c24977cf-b434-51cb-b007-015440be49f0"}, {"title": "朱全忠亲军进击朱瑄，屯鱼山", "start_year": 894, "end_year": 894, "time_original": "894年二月", "dynasty": "唐", "description": "朱全忠亲自领军攻朱瑄，在鱼山驻军。", "phases": [], "location_name": "鱼山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c4ba9741-3035-54ef-a213-cf7a84e3dc3e"}, {"title": "朱瑄朱瑾合击鱼山，兗郓军大败", "start_year": 894, "end_year": 894, "time_original": "894年二月", "dynasty": "唐", "description": "朱瑄与朱瑾合兵攻朱全忠，兗郓军大败，书载死者一万余人。", "phases": [], "location_name": "鱼山", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4b5b9005-63ec-5487-8763-2127ddf97a3e"}, {"title": "郑綮被授礼部侍郎同平章事", "start_year": 894, "end_year": 894, "time_original": "894年二月条；具体日未载", "dynasty": "唐", "description": "朝廷以右散骑常侍郑綮为礼部侍郎、同平章事；昭宗认为其诗有所寓意，在班簿上亲自批注命为宰相。", "phases": [], "location_name": "朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "49f01931-8d9e-5f0a-b044-a0c0cdf1908e"}, {"title": "郑綮闻任惊讶，多次辞让后视事", "start_year": 894, "end_year": 894, "time_original": "闻任以后；累让不获，乃视事", "dynasty": "唐", "description": "堂吏告知任命时，郑綮以诙谐言语表示难信及忧人取笑；贺客来时又感叹歇后郑五竟作宰相。多次辞让未获准，才就任处理政事。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "b467a738-2c37-588b-b9a2-b100bb58a51a"}, {"title": "邓处讷受任武安节度使", "start_year": 894, "end_year": 894, "time_original": "894年二月条；具体日未载", "dynasty": "唐", "description": "朝廷任邵州刺史邓处讷为武安节度使。", "phases": [], "location_name": "武安、邵州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4c424201-cf51-553c-8850-4e413b92bb5c"}, {"title": "张钧去世，曾表请兄张鐇为留后", "start_year": 894, "end_year": 894, "time_original": "894年二月条；卒及表的确日未载", "dynasty": "唐", "description": "彰义节度使张钧去世，原文同记其上表请兄张鐇为留后。", "phases": [], "location_name": "彰义", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9020d02c-a391-5f3c-9e87-2b4f99f4b48e"}, {"title": "吴讨举黄州降杨行密", "start_year": 894, "end_year": 894, "time_original": "894年三月", "dynasty": "唐", "description": "黄州刺史吴讨带所辖州归降杨行密。", "phases": [], "location_name": "黄州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "d0c6e4d0-17b3-55e7-9b67-c794e6beb768"}, {"title": "邢州粮尽，李存孝登城请见李克用", "start_year": 894, "end_year": 894, "time_original": "894年三月甲申", "dynasty": "唐", "description": "邢州城内粮尽，李存孝登城向李克用请求见面，称自己受王恩、因谗言才背离父子关系而附仇敌。", "phases": [], "location_name": "邢州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "3c80bcc5-6e8a-5022-a629-3fe967c2bd7d"}, {"title": "刘夫人引李存孝出城见李克用", "start_year": 894, "end_year": 894, "time_original": "894年三月甲申条后；具体时刻未载", "dynasty": "唐", "description": "李克用派刘夫人探视李存孝；刘夫人带存孝出城见李克用。存孝叩首认罪，称李存信逼使自己失策；李克用反问他寄朱全忠、王镕的信中尽毁自己，难道也是存信教的。", "phases": [], "location_name": "邢州城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "2b72e463-1347-55e4-ada5-09f5bd12b31c"}, {"title": "李存孝被囚，押回晋阳", "start_year": 894, "end_year": 894, "time_original": "见李克用后；押回确日未载", "dynasty": "唐", "description": "李克用拘囚李存孝，将他押回晋阳。", "phases": [], "location_name": "邢州、晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "31307a02-ca82-564d-848a-3335ec89c397"}, {"title": "李存孝在晋阳牙门被车裂", "start_year": 894, "end_year": 894, "time_original": "894年；押回晋阳后，确日未载", "dynasty": "唐", "description": "李存孝押回晋阳后，在牙门被车裂。", "phases": [], "location_name": "晋阳、牙门", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b8b1e0b0-6d7e-5381-a3a1-ab9ad84eca67"}, {"title": "李克用惜李存孝之才，欲待诸将求情而无言", "start_year": 894, "end_year": 894, "time_original": "李存孝临刑时；确日未载", "dynasty": "唐", "description": "《通鉴》叙李克用珍惜李存孝的才能，意欲在临刑时等诸将求情，再因而赦免；诸将嫉其才能，无人出言。", "phases": [], "location_name": "晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "97e3ae50-4b12-5cd7-a167-a220461d425e"}, {"title": "李克用因李存孝死十日不视事，未谴李存信", "start_year": 894, "end_year": 894, "time_original": "李存孝死后；不视事旬日", "dynasty": "唐", "description": "李存孝死后，李克用十日不处理政事，私下恨诸将，却未责罚李存信。", "phases": [], "location_name": "晋阳", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ce40ebc2-c904-5e46-9a4c-b8f3a52b7b60"}, {"title": "李存孝被诛后，薛阿檀因恐泄事自杀", "start_year": 894, "end_year": 894, "time_original": "894年；李存孝被诛以后", "dynasty": "唐", "description": "薛阿檀私下与李存孝通信，李存孝被诛后，怕事情泄露，遂自杀。", "phases": [], "location_name": "", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "原文未给单一地点。", "status": "draft", "id": "f348f7b3-f522-523c-b90e-bac238e36620"}, {"title": "李克用表请马师素为邢洺节度使", "start_year": 894, "end_year": 894, "time_original": "894年三月条末；具体日未载", "dynasty": "唐", "description": "李克用上表请任马师素为邢洺节度使。", "phases": [], "location_name": "邢洺", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f148db1c-3bd2-5669-8ae4-1157acbe52fa"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

